"""
Bridge registry for the BridgeTwinAI MVP.

Every attribute carries an explicit provenance label so that the UI can
distinguish between:

* ``public``    – taken from publicly available information (should be cited/verified)
* ``estimated`` – derived from public information using documented assumptions
* ``assumed``   – no public source; a project assumption for demonstration
* ``simulated`` – generated by the simulator (never real measurements)

To add a new bridge, append a ``BridgeProfile`` to ``BRIDGES`` – no other
code needs to change.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime
from typing import Dict, List, Literal

Provenance = Literal["public", "estimated", "assumed", "simulated"]

# --- Traffic normalisation constants (standard traffic-engineering factors) ---
# The XGBoost model was trained on Traffic_Volume values in the range 51–4,994.
# Real bridges are reported as Average Daily Traffic (ADT). We convert ADT to a
# peak-hour, peak-direction volume, which falls inside the training range:
#     peak_dir_vph = ADT × K × D
K_FACTOR = 0.09  # share of daily traffic in the design peak hour (typ. 0.08–0.10)
D_FACTOR = 0.55  # share of peak-hour traffic in the peak direction (typ. 0.55–0.60)
HEAVY_VEHICLE_SHARE = 0.12  # assumed share of heavy goods vehicles (fatigue loading)


@dataclass(frozen=True)
class BridgeProfile:
    id: str
    name: str
    lat: float
    lon: float
    structure_type: str  # used by the 3D twin: "girder" | "cable-stayed" | "segmental"
    opened_year: int
    length_m: float
    material_type: Literal["Steel", "Concrete"]  # simplified for the XGBoost model
    material_detail: str
    adt_vehicles_per_day: int
    maintenance_level: Literal["No-Maintainance", "Annual", "Bi-Annual"]
    design_life_years: int
    exposure_class: str
    description: str
    provenance: Dict[str, Provenance] = field(default_factory=dict)
    notes: List[str] = field(default_factory=list)
    fixed_age: int | None = None

    @property
    def age_years(self) -> int:
        if self.fixed_age is not None:
            return self.fixed_age
        return max(datetime.now().year - self.opened_year, 1)

    @property
    def peak_direction_vph(self) -> float:
        return round(self.adt_vehicles_per_day * K_FACTOR * D_FACTOR, 1)

    def model_inputs(self) -> Dict[str, object]:
        """Inputs for the XGBoost condition classifier (training-schema names)."""
        return {
            "Age_of_Bridge": self.age_years,
            "Traffic_Volume": self.peak_direction_vph,
            "Material_Type": self.material_type,
            "Maintenance_Level": self.maintenance_level,
        }


